


-- 02_data.sql  |  Test data: 10 rows in each main table.  Run AFTER 01_tables.sql (Run Script, F5).
-- Test password for every user: Passw0rd!   Dates are relative to the day you run this file.
SET DEFINE OFF;










COMMIT;

-- Because the test rows have fixed IDs, move each ID counter past them so new rows from the app get fresh IDs.
ALTER TABLE USERS MODIFY (USER_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE USER_PHONES MODIFY (PHONE_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE SCHOOLS MODIFY (SCHOOL_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE BUSES MODIFY (BUS_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE STUDENTS MODIFY (STUDENT_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE STUDENT_LOCATIONS MODIFY (LOCATION_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE TRIPS MODIFY (TRIP_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE BUS_ROUTES MODIFY (ROUTE_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE GPS_PINGS MODIFY (PING_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE INCIDENT_LOGS MODIFY (INCIDENT_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE AUDIT_LOGS MODIFY (AUDIT_ID GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));

-- Quick check: row counts
SELECT 'USERS' AS TBL, COUNT(*) AS ROWS_N FROM USERS UNION ALL SELECT 'SCHOOLS', COUNT(*) FROM SCHOOLS UNION ALL
SELECT 'BUSES', COUNT(*) FROM BUSES UNION ALL SELECT 'STUDENTS', COUNT(*) FROM STUDENTS UNION ALL SELECT 'TRIPS', COUNT(*) FROM TRIPS UNION ALL
SELECT 'BUS_ROUTES', COUNT(*) FROM BUS_ROUTES UNION ALL SELECT 'GPS_PINGS', COUNT(*) FROM GPS_PINGS UNION ALL
SELECT 'INCIDENT_LOGS', COUNT(*) FROM INCIDENT_LOGS UNION ALL SELECT 'AUDIT_LOGS', COUNT(*) FROM AUDIT_LOGS;
